begin;
set local search_path=public,extensions;
select no_plan();
create temporary table offline_fixture(credential jsonb,lot_id uuid,envelope jsonb);
grant all on offline_fixture to authenticated;
create function pg_temp.signed_decision(target uuid,dev uuid) returns jsonb language plpgsql security definer as $$
declare e jsonb; c jsonb; secret bytea; message text;
begin
 select credential into c from offline_fixture;
 select oc.secret into secret from private.offline_credential oc where oc.id=(c->>'id')::uuid;
 e:=jsonb_build_object('id',gen_random_uuid(),'cooperative_id','10000000-0000-4000-8000-000000000001','author_id','20000000-0000-4000-8000-000000000001','device_id',dev,'config_version_id','40000000-0000-4000-8000-000000000001','action','whey_decision','observed_at',now(),'payload',jsonb_build_object('lot_id',target,'outcome','accepted','reason','Received within configured limits','credential_id',c->>'id'));
 message:=concat_ws(E'\n',e->>'id',e->>'cooperative_id',e->>'author_id',e->>'device_id',e->>'config_version_id',e->'payload'->>'lot_id',e->>'observed_at',e->'payload'->>'outcome',e->'payload'->>'reason');
 return jsonb_set(e,'{payload,proof}',to_jsonb(encode(extensions.hmac(convert_to(message,'UTF8'),secret,'sha256'),'hex')));
end $$;
grant execute on function pg_temp.signed_decision(uuid,uuid) to authenticated;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"20000000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal1"}',true);
insert into offline_fixture(credential,lot_id) values(public.issue_offline_credential('30000000-0000-4000-8000-000000000001',public.pin_signoff('2468','30000000-0000-4000-8000-000000000001','cache_session','20000000-0000-4000-8000-000000000001')),gen_random_uuid());
select ok((select credential->>'secret' ~ '^[a-f0-9]{64}$' from offline_fixture),'Online PIN issues a device-bound signing key');
select is(public.apply_sync(jsonb_build_object('id',(select lot_id from offline_fixture),'cooperative_id','10000000-0000-4000-8000-000000000001','author_id','20000000-0000-4000-8000-000000000001','device_id','30000000-0000-4000-8000-000000000001','config_version_id','40000000-0000-4000-8000-000000000001','action','receipt','observed_at',now(),'payload',jsonb_build_object('type','whey','supplier_id','50000000-0000-4000-8000-000000000001','unit','kg','quantity',5,'generation_at',now()-interval '1 hour','facts',jsonb_build_object('ph',5,'reception_temperature',5))))->>'status','synced','Receipt can sync before its offline decision');
update offline_fixture set envelope=pg_temp.signed_decision(lot_id,'30000000-0000-4000-8000-000000000001');
select is(public.apply_sync(jsonb_set((select envelope from offline_fixture),'{payload,reason}','"Tampered justification"'))->>'status','conflict','Changing a signed reason invalidates proof');
select is((select state from public.lot where id=(select lot_id from offline_fixture)),'received','Invalid proof leaves the decision unapplied');
update offline_fixture set envelope=pg_temp.signed_decision(lot_id,'30000000-0000-4000-8000-000000000001');
select is(public.apply_sync(jsonb_set((select envelope from offline_fixture),'{payload,outcome}','"rejected"'))->>'status','conflict','Changing the signed outcome invalidates proof');
select lives_ok($$select public.register_device('30000000-0000-4000-8000-000000000033','Other receiving device')$$,'Second device registered for negative test');
select is(public.apply_sync(pg_temp.signed_decision((select lot_id from offline_fixture),'30000000-0000-4000-8000-000000000033'))->>'status','conflict','An otherwise valid proof cannot move to another device');
select is(public.apply_sync(pg_temp.signed_decision('60000000-0000-4000-8000-000000000005','30000000-0000-4000-8000-000000000001'))->>'status','conflict','Offline receiving cannot override a decision on a seed lot from another device');
update offline_fixture set envelope=pg_temp.signed_decision(lot_id,'30000000-0000-4000-8000-000000000001');
select is(public.apply_sync((select envelope from offline_fixture))->>'status','synced','Authentic offline receiving decision is applied');
select is((select state from public.lot where id=(select lot_id from offline_fixture)),'accepted','Accepted state is backed by a server-verified signature');
select is(public.apply_sync((select envelope from offline_fixture))->>'status','synced','Resending the same signature is idempotent');
reset role;
update private.offline_credential set expires_at=now()-interval '1 second' where id=(select (credential->>'id')::uuid from offline_fixture);
set local role authenticated;
select is(public.apply_sync(pg_temp.signed_decision((select lot_id from offline_fixture),'30000000-0000-4000-8000-000000000001'))->>'status','conflict','Expired signing credential is retained for review rather than accepted');
select ok(not has_table_privilege('authenticated','private.offline_credential','select'),'Application role cannot read stored signing keys');
select throws_ok($$select public.impact_metrics('2026-01-01','2026-12-31')$$,'P0001','Dashboard permission required','Producer cannot query impact aggregates');
select set_config('request.jwt.claims','{"sub":"20000000-0000-4000-8000-000000000002","role":"authenticated","aal":"aal1"}',true);
select throws_ok($$select public.impact_metrics('2026-01-01','2026-12-31')$$,'P0001','Dashboard permission required','Supervisor cannot query impact aggregates');
select ok(not has_function_privilege('authenticated','private.impact_metrics(date,date)','execute'),'Dashboard permission wrapper cannot be bypassed');
select * from finish();
rollback;
